{
  "url": "https://x402meta.hergertsynthora.com/service",
  "results": [
    {
      "method": "POST",
      "source": "openapi",
      "summary": "SYNTHORA x402 preflight / endpoint reputation",
      "authMode": "paid",
      "estimatedPrice": "0.010000 USD",
      "currency": "USD",
      "protocols": [
        "x402"
      ],
      "inputSchema": {
        "type": "object",
        "properties": {
          "endpoint_url": {
            "type": "string",
            "description": "x402 endpoint URL to preflight (https://..)"
          },
          "payTo": {
            "type": "string",
            "description": "Alternatively, a payTo address (0x..) to reputation-check"
          },
          "prev": {
            "type": "object",
            "description": "Optional prior snapshot {payTo,amount,lastUpdated} for anti-rug change detection"
          }
        }
      },
      "requiresPayment": true
    }
  ]
}

{
  "url": "https://paddock.finance/api/paddock/mcp/verify-before-pay",
  "results": [
    {
      "method": "GET",
      "source": "openapi",
      "summary": "Should my agent pay this endpoint right now?",
      "authMode": "apiKey+paid",
      "inputSchema": {
        "parameters": [
          {
            "name": "endpoint_url",
            "in": "query",
            "required": false,
            "description": "The resource URL your agent is about to pay. This is the URL that gets probed.",
            "schema": {
              "type": "string",
              "format": "uri"
            }
          },
          {
            "name": "pay_to",
            "in": "query",
            "required": false,
            "description": "The recipient wallet from the 402 you are about to settle. CHECKED: if it is not one of the recipients the live challenge names, route is false and pay_to is in mismatched_fields. Give this, endpoint_url, or both — at least one is required.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "expect_network",
            "in": "query",
            "required": false,
            "description": "Network you expect, CAIP-2 or shorthand (eip155:8453 / base). Mismatch returns route:false.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "expect_asset",
            "in": "query",
            "required": false,
            "description": "Asset contract address you expect. Mismatch returns route:false.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "expect_seller",
            "in": "query",
            "required": false,
            "description": "Seller domain you expect. Satisfied by the live 402's own resource host or by Paddock's payTo attribution. Mismatch returns route:false.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "expect_price_usdc",
            "in": "query",
            "required": false,
            "description": "Price in dollars you expect to pay, e.g. 0.01. ANY difference returns route:false and names the field.",
            "schema": {
              "type": "number",
              "minimum": 0
            }
          },
          {
            "name": "intended_params",
            "in": "query",
            "required": false,
            "description": "Parameter NAMES your request will carry, comma-separated or as a query string ('slug,limit' or '?slug=amazon-us'). Values are discarded, never stored. Compared against the parameter schema the live 402 declares; a missing required name is reported in checks.requestPreflight and does NOT change route.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "intended_params_empty",
            "in": "query",
            "required": false,
            "description": "Assert that your paid request will carry NO parameters at all. Bare (?intended_params_empty) or =true. This is an assertion and it is checked: against a challenge that declares anything required, an empty request fails pre-flight, where omitting the argument entirely reports 'you did not say' and checks nothing. Passing this together with intended_params is a 400 — they are contradictory statements about one request.",
            "schema": {
              "type": "boolean"
            }
          }
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "tool": {
            "type": "string",
            "const": "verify_before_pay"
          },
          "schema_version": {
            "type": "string",
            "description": "Bumped when a stored response stops being comparable to a live one: a breaking shape change, a change to what an existing field means, or a new verdict the older version did not emit. Store it with the verdict — a verdict is only comparable to another at the same version."
          },
          "checked_at": {
            "type": "string",
            "format": "date-time",
            "description": "When the live probe ran. The whole value of this response is that it was taken at this instant; it is never cached."
          },
          "route": {
            "description": "true = the endpoint asked for payment and the contract you stated matched. false = do not pay. \"inconclusive\" = either we could not read a 402, so we cannot vouch for what it will charge you, or you supplied no pay_to and no expect_* so there was nothing to compare (reason code no_expectations_supplied).",
            "oneOf": [
              {
                "type": "boolean"
              },
              {
                "type": "string",
                "const": "inconclusive"
              }
            ]
          },
          "route_state": {
            "description": "route_state carries the same verdict as route, always as a string (\"true\", \"false\", \"inconclusive\"), for clients that cannot type a boolean-or-string field.",
            "type": "string",
            "enum": [
              "true",
              "false",
              "inconclusive"
            ]
          },
          "contract_and_request_ok": {
            "description": "The combined verdict (0.6). true only when the live contract matched your expectations (route === true) AND your own declared request passed pre-flight (checks.requestPreflight.status === \"pass\"). false when either term is bad — including when YOUR request is missing a parameter the challenge declares required. The STRING \"not_assessed\" when a term was never established, most often because you passed no intended_params or intended_params_empty, so there was no request of yours to clear; that is not a soft yes and not a no. Test with contract_and_request_ok === true. It does not replace route, which is unchanged, and it is NOT a clearance — read contract_and_request_ok_excludes.",
            "oneOf": [
              {
                "type": "boolean"
              },
              {
                "type": "string",
                "const": "not_assessed"
              }
            ]
          },
          "contract_and_request_ok_excludes": {
            "type": "array",
            "description": "Every risk category the conjunction does NOT cover, each with the field where that category's own verdict lives and what it can be doing while contract_and_request_ok is true: settlement recency, an unassessed circular signal, attribution divergence, a payTo-only divergence from the seller's published config, a divergent second challenge channel, and price against the category median. The list is STATIC — it says what the formula leaves out, not how this endpoint scored, so coverage can never be inferred from an absence.",
            "items": {
              "type": "object",
              "properties": {
                "category": {
                  "type": "string"
                },
                "where": {
                  "type": "string"
                },
                "note": {
                  "type": "string"
                }
              }
            }
          },
          "reason_codes": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Stable, append-only vocabulary, e.g. live_402_observed, contract_mismatch_price, circular_flagged_cluster_member, settlement_never_observed."
          },
          "summary": {
            "type": "string"
          },
          "route_note": {
            "type": "string"
          },
          "paddock_url": {
            "type": [
              "string",
              "null"
            ],
            "description": "The paddock.finance/s/<domain> service page for this target, when one exists; null otherwise. Additive, non-breaking (no schema_version bump)."
          },
          "target": {
            "type": "object",
            "description": "What was probed, what the wallet resolved to, and which wallet the circular check used."
          },
          "expectations_supplied": {
            "type": "object"
          },
          "checks": {
            "type": "object",
            "description": "One block per check, each carrying its own status, universe, basis and as_of date. No figure in one block is divided by a figure in another.",
            "properties": {
              "liveness": {
                "type": "object"
              },
              "contract": {
                "type": "object"
              },
              "settlement": {
                "type": "object"
              },
              "circular": {
                "type": "object"
              },
              "paid_fulfillment": {
                "type": "object",
                "description": "Independent third-party paid-verification result, re-served under CC-BY 4.0. Carries status, last_paid_attempt_at (the date the SOURCE observed it, never defaulted to now), basis, attribution_url, and the settlement tx_hash where one was published. Absent coverage returns not_assessed with a basis naming why."
              },
              "price": {
                "type": "object"
              }
            }
          },
          "evidence": {
            "type": "array",
            "description": "One row per fact, each with the source it came from and the time it is as-of. Probe rows are as-of now; snapshot and classification rows are as-of their own dates, which are older.",
            "items": {
              "type": "object",
              "properties": {
                "check": {
                  "type": "string"
                },
                "observed_at": {
                  "type": "string",
                  "format": "date-time"
                },
                "source": {
                  "type": "string"
                },
                "detail": {
                  "type": "string"
                }
              }
            }
          },
          "_meta": {
            "type": "object"
          }
        }
      },
      "requiresPayment": true
    }
  ]
}

{
  "url": "https://merchant-audit.clankerceo.workers.dev/x402-endpoint-verify",
  "results": [
    {
      "method": "GET",
      "source": "openapi",
      "summary": "Due-diligence audit of an x402 merchant",
      "authMode": "paid",
      "estimatedPrice": "0.01 USD",
      "currency": "USD",
      "protocols": [
        "x402"
      ],
      "inputSchema": {
        "parameters": [
          {
            "name": "target",
            "in": "query",
            "required": true,
            "schema": {
              "type": "string"
            },
            "example": "https://example-merchant.com/api/some-service",
            "description": "Absolute https URL of the x402 resource to audit."
          }
        ]
      },
      "outputSchema": {
        "type": "object"
      },
      "requiresPayment": true
    }
  ]
}
